	/*
     * @param	event CreateTerritoryEvent
     */
    @EventHandler( payloadType=CreateTerritoryEvent.class )
    public void handle( CreateTerritoryEvent event) {
	    LOGGER.info("handling CreateTerritoryEvent - " + event );
	    Territory entity = new Territory();
            entity.setTerritoryId( event.getTerritoryId() );
            entity.setName( event.getName() );
            entity.setRegion( event.getRegion() );
            entity.setTerritoryType( event.getTerritoryType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllTerritory( entity );
    }

    /*
     * @param	event UpdateTerritoryEvent
     */
    @EventHandler( payloadType=UpdateTerritoryEvent.class )
    public void handle( UpdateTerritoryEvent event) {
    	LOGGER.info("handling UpdateTerritoryEvent - " + event );
    	
	    Territory entity = new Territory();
            entity.setTerritoryId( event.getTerritoryId() );
            entity.setName( event.getName() );
            entity.setRegion( event.getRegion() );
            entity.setOrganization( event.getOrganization() );
            entity.setAccounts( event.getAccounts() );
            entity.setUsers( event.getUsers() );
            entity.setTerritoryType( event.getTerritoryType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindTerritory( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllTerritory( entity );        
    }
    
