    /**
     * Method to retrieve the Territory via an TerritoryPrimaryKey.
     * @param 	id Long
     * @return 	Territory
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Territory handle( FindTerritoryQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getTerritoryId() );
    }
    
    /**
     * Method to retrieve a collection of all Territorys
     *
     * @param	query	FindAllTerritoryQuery 
     * @return 	List<Territory> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Territory> handle( FindAllTerritoryQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindTerritory,
 * but only if the id matches
 *
 * @param		entity	Territory
 */
	protected void emitFindTerritory( Territory entity ) {
		LOGGER.info("handling emitFindTerritory" );
		
	    queryUpdateEmitter.emit(FindTerritoryQuery.class,
	                            query -> query.getFilter().getTerritoryId().equals(entity.getTerritoryId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTerritory
	 * 
	 * @param		entity	Territory
	 */
	protected void emitFindAllTerritory( Territory entity ) {
		LOGGER.info("handling emitFindAllTerritory" );
		
	    queryUpdateEmitter.emit(FindAllTerritoryQuery.class,
	                            query -> true,
	                            entity);
	}

